sources.src/trama/application/adjudication.py:
"""Pedidos contextuais na decisão do Mundo existente; sem chamadas ao provedor.

Os pedidos de acústica descrevem barreiras/categoria de emissão e são reutilizados
enquanto esses fatos persistem. Distância, sentido e CD fixa continuam no motor.
"""

from copy import deepcopy
from dataclasses import asdict
import json
import logging

from trama.actions import ActionError
from trama.characters import ability_check
from trama.difficulty import Adjudication
from trama.perception import Noise, Observer, Senses

logger = logging.getLogger(__name__)


class AdjudicationSystem:
    def __init__(self, session):
        self.session = session
        self.issued = {}
        self.cached = {}
        self.strict = False
        self.hearing_records = set()
        self.approach = ''

    def _request(self, id, kind, skill, description, facts):
        return dict(id=id, kind=kind, skill=skill, description=description, facts=facts)

    def _fingerprint(self, request):
        return json.dumps(request, sort_keys=True, ensure_ascii=False)

    def _current(self, request):
        entry = self.cached.get(request['id'])
        return entry['decision'] if entry and entry['fingerprint'] == self._fingerprint(request) else None

    def acoustic_request(self, passage_ids, volume, *, speech=False):
        passages = {p.id: p for p in self.session.scene.passages} if self.session.scene else {}
        facts = {f'door:{id}': dict(name=passages[id].name, is_open=passages[id].is_open,
                                  description=passages[id].description,
                                  connects=list(passages[id].connects)) for id in sorted(passage_ids)}
        facts['sound:volume'] = volume
        facts['sound:purpose'] = 'understand_speech' if speech else 'notice_noise'
        return self._request('hearing:' + ('speech:' if speech else 'noise:') + volume + ':' + ','.join(sorted(passage_ids)), 'hearing', 'perception',
            ('Compreender as palavras de uma fala através destas portas. ' if speech else
             'Perceber um ruído através destas portas, sem identificar sua fonte ou compreender palavras. ') +
            'Distância e capacidade do ouvinte são verificadas separadamente pelo código.', facts)

    def prepare(self, steps, *, approach=''):
        self.approach = approach
        requests = {r['id']: r for r in self.session.contextual_check_requests(steps)}
        noisy = not steps or any((not s.get('clarification') and s.get('operation') in {'move', 'open', 'close', 'speak', 'challenge', 'sneak', 'wait', 'wake'})
            or s.get('operation') == 'inspect_passage' and s.get('method') == 'mechanism'
            or any(p.get('proposed_path') for p in s.get('preparation', [])) for s in steps)
        s = self.session
        if noisy and s.scene:
            player = Observer(s.encounter.player_id, 'Jogador', s.state.position,
                              Senses(perception_bonus=s.encounter.player_sheet.skill_bonus('perception')))
            listeners = (*s.perception.observers(), player)
            sources = [(o.id, o.position) for o in listeners]
            # Prévia determinística de caminhos; nenhuma percepção/ação é aplicada.
            for step in steps:
                for path in [step.get('proposed_path', []), *(p.get('proposed_path', []) for p in step.get('preparation', []))]:
                    from trama.spatial import Position
                    sources.extend((player.id, Position(x - 1, y - 1)) for x, y in path)
            for source_id, position in dict.fromkeys(sources):
                for listener in listeners:
                    if listener.id == source_id or not listener.senses.can_hear:
                        continue
                    doors = s.perception.sound_barriers(position, listener.position)
                    if not doors:
                        continue
                    for volume in ('quiet', 'normal', 'loud'):
                        noise = Noise(source_id, position, volume)
                        if not s.perception.hears(listener, noise, adjudicate=False):
                            continue
                        for speech in (False, True):
                            request = self.acoustic_request(doors, volume, speech=speech)
                            requests[request['id']] = request
        self.issued = {id: r for id, r in requests.items() if self._current(r) is None}
        if len(self.issued) > 32:
            raise ActionError('Há mais de 32 avaliações contextuais; reduza o plano.')
        return dict(requests=deepcopy(list(self.issued.values())), cached=[dict(request_id=id,
            **{k: v for k, v in self._current(r).context().items() if k != 'request_id'})
            for id, r in requests.items() if self._current(r) is not None])

    def begin(self, decisions, *, strict=False):
        proposed = {a.request_id: a for a in decisions}
        if set(proposed) - self.issued.keys():
            raise ActionError('O Mundo avaliou uma dificuldade não solicitada ou de regra fixa.')
        if strict and self.issued.keys() - proposed.keys():
            raise ActionError('O Mundo não avaliou todas as dificuldades contextuais solicitadas.')
        # Validar tudo antes de instalar qualquer decisão.
        for id, decision in proposed.items():
            if not set(decision.fact_ids) <= self.issued[id]['facts'].keys():
                raise ActionError('A avaliação cita um fato não fornecido pelo estado atual.')
        for id, decision in proposed.items():
            self.cached[id] = dict(decision=decision, fingerprint=self._fingerprint(self.issued[id]))
            logger.info('adjudication.decided', extra={'data': dict(request=self.issued[id], decision=decision.context())})
        self.strict = strict
        self.hearing_records.clear()

    def decision(self, request, fallback_dc):
        decision = self._current(request)
        if decision is not None:
            return decision
        if self.strict:
            raise ActionError('Falta avaliação para o contexto atual: ' + request['id'])
        # Preparações sem IA e consumidores determinísticos mantêm o recorte
        # declarado do cenário. O caminho oficial com Mundo exige adjudicação.
        from trama.difficulty import DIFFICULTY_CLASSES
        level = next((k for k, v in DIFFICULTY_CLASSES.items() if v >= fallback_dc), 'nearly_impossible')
        return Adjudication(request['id'], 'check', level, False, False,
                            (next(iter(request['facts'])),), 'Recorte determinístico sem adjudicador de IA.')

    def check(self, id, actor, skill, fallback_dc):
        request = self.session.contextual_check(id)
        if request is None or request['skill'] != skill:
            raise ActionError('Teste contextual desconhecido ou perícia incompatível.')
        decision = self.decision(request, fallback_dc)
        default = self._current(request) is None
        dc = fallback_dc if default else decision.dc
        passed = decision.outcome == 'automatic'
        result = dict(operation='check', actor_id=actor, skill=skill, changed=False,
                      perceptible=actor == self.session.encounter.player_id,
                      adjudication_id=id, adjudication=decision.context(), automatic=decision.outcome != 'check',
                      dc=dc, dice=[], total=None, passed=passed)
        if default:
            result['adjudication'] = {'source': 'scenario_default', 'dc': fallback_dc,
                                      'reason': 'Preparação/execução determinística sem avaliação de IA.'}
        if decision.outcome == 'check':
            sheet = self.session.encounter.sheets[actor]
            state, roll, total = ability_check(sheet, self.session.encounter.states[actor], skill, dc,
                self.session.encounter.roller, advantage=decision.advantage, disadvantage=decision.disadvantage)
            self.session.encounter.states[actor] = state
            passed = total >= dc
            result.update(dice=list(roll.dice), total=total, passed=passed,
                          advantage=roll.advantage, disadvantage=roll.disadvantage)
        self.session._events.append(result)
        logger.info('adjudication.check_resolved', extra={'data': result})
        return passed, result['total']

    def hearing(self, listener, noise, barriers):
        if not barriers:
            return None
        request = self.acoustic_request(barriers, noise.volume, speech=noise.speech)
        decision = self._current(request)
        if decision is None:
            if self.strict:
                raise ActionError('Falta avaliação acústica: ' + request['id'])
            return None
        return decision

    def record_hearing(self, listener, noise, decision, total, dc, heard):
        if not self.strict:
            return
        key = (listener.id, noise.actor_id, listener.position, noise.position, noise.volume, decision.request_id)
        if key in self.hearing_records:
            return
        self.hearing_records.add(key)
        event = dict(operation='hearing_check', actor_id=listener.id, target_id=noise.actor_id,
            perceptible=listener.id == self.session.encounter.player_id, changed=False,
            adjudication_id=decision.request_id, automatic=decision.outcome != 'check' and dc is None,
            dc=dc, total=total, passed=heard, disadvantage=decision.disadvantage, advantage=decision.advantage,
            purpose='understand_speech' if noise.speech else 'notice_noise', volume=noise.volume)
        self.session._events.append(event)
        logger.info('adjudication.hearing_resolved', extra={'data': event})

sources.src/trama/application/authorization.py:
"""Validação declarativa do plano; a interpretação do português pertence à IA.

Trechos e classificações são dados externos auditáveis, não uma prova semântica
de consentimento. Regras de estado continuam validadas pela sessão a cada etapa.
"""

import logging

from trama.application.dialogue import split_speech
from trama.application.intents import ActionPlan, DoorIntent, InspectionIntent, InterpretationError, MovementIntent, RuleIntent, ScenarioIntent

logger = logging.getLogger(__name__)


class PlanAuthorizationError(InterpretationError):
    """Plano inconsistente com suas origens declaradas ou referências do cenário."""


def step_operations(step) -> tuple[str, ...]:
    if isinstance(step, MovementIntent):
        return ("clarify",) if step.clarification else (("move", "dash") if step.dash else ("move",))
    if isinstance(step, RuleIntent) and step.use_inspiration:
        return (step.operation, "inspiration")
    return (step.operation,)


def validate_player_plan(prompt: str, plan: ActionPlan, context: dict | None = None,
                         *, stage: str = "validation") -> None:
    """Verifica origens, cobertura, tipos de intenção e ids, sem gramática de verbos."""
    context = context or {}
    try:
        on = split_speech(prompt).on
        if not on:
            raise PlanAuthorizationError("Fala exclusivamente em off não autoriza ações.")
        if not plan.request_parts:
            raise PlanAuthorizationError("O plano não informa os trechos de origem da mensagem atual.")
        covered = []
        for part in plan.request_parts:
            if part.text not in on:
                raise PlanAuthorizationError("O trecho de origem não pertence ao pedido on atual.")
            if any(i >= len(plan.steps) for i in part.step_indices):
                raise PlanAuthorizationError("A origem aponta para uma etapa inexistente.")
            operations = tuple(op for i in part.step_indices for op in step_operations(plan.steps[i]))
            if operations != part.operations:
                raise PlanAuthorizationError("As operações da origem declarada não correspondem às etapas propostas.")
            if part.kind != "execute" and operations and operations != ("clarify",):
                raise PlanAuthorizationError("Perguntas, negações, citações e detalhes narrativos não autorizam ações.")
            if part.kind in {"question", "negated", "quoted", "narrative_detail"} and part.step_indices:
                raise PlanAuthorizationError("Esse trecho deve ser preservado sem executar etapas.")
            if part.kind == "execute" and not operations:
                raise PlanAuthorizationError("O trecho solicitado não foi mapeado para uma etapa.")
            if part.kind in {"unsupported", "conditional", "unclear"} and operations != ("clarify",):
                raise PlanAuthorizationError("Uma intenção não realizável exige esclarecimento antes de prosseguir.")
            covered.extend(part.step_indices)
        if covered != list(range(len(plan.steps))):
            raise PlanAuthorizationError("Toda etapa precisa de uma origem, na ordem, sem repetição ou omissão.")
        scene = context.get("map", {}).get("scene", {})
        passages = {p["id"] for p in scene.get("passages", [])}
        objects = {o["id"] for o in context.get("visible_objects", [])}
        fixtures = {o["id"] for o in scene.get("objects", []) if o.get("visible")}
        destinations = passages | {a["id"] for a in scene.get("areas", [])} | objects
        visible = {c["id"] for c in context.get("visible_creatures", [])}
        for index, step in enumerate(plan.steps):
            if isinstance(step, MovementIntent):
                if step.clarification and index != len(plan.steps) - 1:
                    raise PlanAuthorizationError("O esclarecimento deve encerrar o plano.")
                if step.target_id is not None and step.target_id not in destinations | visible | fixtures:
                    raise PlanAuthorizationError("O destino não existe no contexto visível do Jogador.")
            elif isinstance(step, (DoorIntent, InspectionIntent)) and step.target_id not in passages:
                raise PlanAuthorizationError("A passagem não existe no contexto do Jogador.")
            elif isinstance(step, ScenarioIntent):
                capabilities = context.get("scenario", {}).get("operations", [])
                if (step.operation not in capabilities and step.operation != "sneak") or step.target_id not in destinations | visible:
                    raise PlanAuthorizationError("Interação ou alvo não disponível neste cenário.")
            elif isinstance(step, RuleIntent):
                if step.operation == "start_combat":
                    raise PlanAuthorizationError("Conflito é resolvido pelo Mundo e pela iniciativa.")
                if step.operation == "attack" and step.target_id not in visible:
                    raise PlanAuthorizationError("O alvo do ataque não existe no contexto visível do Jogador.")
        logger.info("player.plan_authorized", extra={"data": {"stage": stage, "validation": "declarative",
                    "operations": [op for s in plan.steps for op in step_operations(s)]}})
        logger.debug("player.request_sources", extra={"data": {"parts": plan.request_parts}})
    except (ValueError, TypeError) as error:
        logger.warning("player.plan_authorization_rejected", extra={"data": {"stage": stage,
                       "validation": "declarative", "reason": str(error)}})
        if isinstance(error, PlanAuthorizationError):
            raise
        raise PlanAuthorizationError(str(error)) from error

sources.src/trama/application/dungeon.py:
"""Adjudicação do cenário de fuga, sem SDK ou interface.

As CDs, a rotina do guarda e as consequências sociais são decisões de mestre
registradas em docs/sistema/simulador/fuga-da-dungeon.md; não são novas regras universais.
"""

from copy import deepcopy
from dataclasses import dataclass, field, replace
from decimal import Decimal
import logging

from trama.actions import ActionError
from trama.application.encounter import RuleResult
from trama.application.intents import (
    DIRECTIONS, DoorIntent, InspectionIntent, MovementIntent, NarrativeIntent, RuleIntent,
    ScenarioIntent, SCENARIO_OPERATIONS,
)
from trama.application.modes import GameMode
from trama.application.routing import path_to_cells
from trama.application.session import GameSession
from trama.application.preparation import SpatialRequirement
from trama.application.travel import TravelResult, TravelExecutor
from trama.characters import ability_check, sheet_from_data
from trama.creatures import creatures_from_data
from trama.movement import MovementError, MovementResult, MovementState, MovementRequest
from trama.scene import Scene
from trama.spatial import Position
from trama.vision import line_of_sight
from trama.perception import Noise, Observer, Senses, observers_from_data
from trama.knowledge import Claim, initial_memories
from trama.social import profiles_from_data

logger = logging.getLogger(__name__)


def distance(a: Position, b: Position) -> int:
    return max(abs(a.x - b.x), abs(a.y - b.y))


def coordinate(p: Position) -> list[int]:
    return [p.x + 1, p.y + 1]


@dataclass
class DungeonState:
    inventory: set[str] = field(default_factory=set)
    discovered: set[str] = field(default_factory=set)
    exposed_items: set[str] = field(default_factory=set)
    clothing: str = 'rags'
    sword_concealed: bool = False
    disguise: str = 'untested'
    prisoner_awake: bool = False
    prisoner_free: bool = False
    guard_alert: bool = False
    guard_activity: str = 'on_duty'
    bathroom_remaining: int = 0
    waits: int = 0
    illusion_used: bool = False
    distraction_remaining: int = 0
    escaped: bool = False
    companion_escaped: bool = False


class DungeonSession(GameSession):
    """Pequeno cenário sobre as APIs existentes de movimento e combate.

    O prisioneiro é um NPC de cenário, fora do elenco de Guerreiros do combate.
    Nenhuma ficha fictícia de Guerreiro é atribuída ao mago.
    """

    title = 'Simulador / Fuga da dungeon'

    @classmethod
    def from_data(cls, data: dict, *, roller=None):
        scene = Scene.from_data(data)
        player = sheet_from_data(data['player'], id='player', name='Jogador', default_level=3)
        creatures = creatures_from_data(data['creatures'])
        session = cls(scene.movement_grid, MovementState(Position(*data['start']), player.speed_meters), scene,
                      creatures, player_sheet=player,
                      enemy_sheets=tuple(sheet_from_data(c['sheet'], id=c['id'], name=c['name'])
                                         for c in data['creatures']), roller=roller,
                      observers=observers_from_data(data.get('observers', [])) or (Observer(
                          'prisoner', 'Prisioneiro', Position(*data['dungeon']['prisoner_position']),
                          Senses(perception_bonus=0, sleeping=True)),), memories=initial_memories(data),
                      social_profiles=profiles_from_data(data))
        session.definition = deepcopy(data['dungeon'])
        session.items = {i['id']: deepcopy(i) for i in session.definition['items']}
        session.title = data.get('title', cls.title)
        session._initialize_dungeon()
        return session

    def _initialize_dungeon(self):
        prisoner = self.perception.observer('prisoner')
        self.dungeon = DungeonState(prisoner_awake=not self.perception.sleeping(prisoner))
        self.dungeon.exposed_items = {id for id, item in self.items.items() if item['discovery'] == 'visible'}
        self.prisoner_position = prisoner.position
        self.item_positions = {id: Position(*item['position']) for id, item in self.items.items()}
        self._events = []
        self._sword_checked = False
        player = self.encounter.player_id
        self.encounter.states[player] = replace(self.encounter.states[player], javelins_remaining=0)

    def reset(self):
        super().reset()
        self._initialize_dungeon()

    def _event(self, operation, text, *, actor_id='world', perceptible=True, **data):
        event = dict(operation=operation, actor_id=actor_id, text=text, changed=True,
                     perceptible=perceptible, **data)
        self._events.append(event)
        logger.info('dungeon.' + operation, extra={'data': event})
        if operation in {'item_taken', 'drop', 'item_found'} and 'item_id' in data:
            item = data['item_id']
            if operation in {'drop', 'item_found'}:
                self.dungeon.exposed_items.add(item)
            position = self.state.position if operation in {'item_taken', 'drop'} else self.item_positions[item]
            value = 'carried:player' if operation == 'item_taken' else f'position:{position.x + 1},{position.y + 1}'
            self.knowledge.observe(Claim(item, 'location', value), text, position,
                                   context='Manipulação ou descoberta de objeto presenciada.', entities=(actor_id,),
                                   excluded=data.get('unnoticed_by', ()))

    def observable_facts(self):
        yield from super().observable_facts()
        if not hasattr(self, 'dungeon'):
            return
        for id, item in self.items.items():
            if id in self.dungeon.inventory or id not in self.dungeon.exposed_items:
                continue
            position = self.item_positions[id]
            yield dict(claim=Claim(id, 'location', f'position:{position.x + 1},{position.y + 1}'),
                       text=f'{item["name"]} está na coluna {position.x + 1}, linha {position.y + 1}.',
                       position=position, context='Objeto exposto observado diretamente.', entities=(item['area'],))

    def on_knowledge(self, memory):
        if (hasattr(self, 'dungeon') and memory.owner_id == self.encounter.player_id
                and memory.claim.subject_id in self.items):
            self.dungeon.discovered.add(memory.claim.subject_id)

    def _passage(self, id):
        passage = next((p for p in self.scene.passages if p.id == id), None)
        if passage is None:
            raise ActionError('Passagem desconhecida.')
        return passage

    def _near(self, position):
        return (distance(self.state.position, position) <= 1
                and line_of_sight(self.state.position, position, self.scene.opaque))

    def _area(self):
        area = self.scene.area_at(self.state.position)
        return area.id if area else None

    @property
    def guard(self):
        return next(c for c in self.creatures if c.id == 'guard_1')

    def _guard_available(self):
        return self.encounter.states['guard_1'].hp > 0

    def _guard_sees_player(self):
        return self._guard_available() and self.npc_sees_player('guard_1')

    def contextual_check(self, id):
        def make(id, kind, skill, description, facts):
            return self.adjudication._request(id, kind, skill, description,
                {**facts, 'approach:player': self.adjudication.approach})
        if id == 'find_uniform' and 'cleaner_uniform' not in self.dungeon.discovered:
            return make(id, 'hidden_object', 'perception', 'Encontrar a roupa de limpeza escondida sob a cama durante uma busca.',
                {'place:cell_4': self.scene.area_at(self.item_positions['cleaner_uniform']).description,
                 'item:cleaner_uniform': 'Roupa de empregado bem escondida sob a cama; não é a espada visível entre os panos.',
                 'light:cell_4': ('dark' if self.item_positions['cleaner_uniform'] in self.scene.dark else
                                  'dim' if self.item_positions['cleaner_uniform'] in self.scene.dim else 'bright')})
        if id == 'steal_key' and self._guard_available():
            return make(id, 'unnoticed_theft', 'sleight_of_hand', 'Pegar a chave da mesa sem que o guarda presente perceba o furto.',
                {'item:cell_key': 'Chave exposta sobre a mesa; não está em bolso nem trancada.',
                 'observer:guard_1': 'Avaliação condicionada à presença de um guarda com visão do furto. '
                     'Se ele não puder observar, o código não exige este teste. Um disfarce aceito não oculta a mão.'})
        if id == 'detect_sword':
            return make(id, 'concealed_object', 'perception', 'O guarda examina se o visitante esconde uma espada longa sob o uniforme.',
                {'item:longsword': 'Espada longa ocultada sob uma roupa de empregado, não invisibilidade mágica.',
                 'observer:guard_1': 'Guarda presente com visão do visitante; examina o volume sob a roupa.'})
        if id.startswith('listen:'):
            target = id.split(':', 1)[1]
            if target not in {'gate_2', 'guard_door', 'bathroom_door'}:
                return None
            passage = self._passage(target)
            sound = ('Respiração discreta de um prisioneiro.' if target == 'gate_2' else
                     'Movimentos e resmungos em volume normal do guarda, na área em que ele realmente está.')
            return make(id, 'listen', 'perception', 'Escutar atentamente do lado da passagem, sem abri-la.',
                {f'passage:{target}': {'kind': passage.kind, 'is_open': passage.is_open, 'name': passage.name,
                                     'description': passage.description},
                 'sound:source': sound, 'activity:guard': self.dungeon.guard_activity})
        return None

    def contextual_check_requests(self, steps):
        ids = set()
        for step in steps:
            operation, target = step['operation'], step.get('target_id')
            if operation == 'investigate' and target == 'cell_4':
                ids.add('find_uniform')
            if operation == 'listen':
                ids.add('listen:' + target)
            if operation == 'take' and target == 'cell_key' and self._guard_available() and self.perception.sees(self.guard, self.item_positions['cell_key']):
                ids.add('steal_key')
        might_conceal = self.dungeon.sword_concealed or any(s['operation'] == 'conceal' for s in steps)
        has_sword = 'longsword' in self.dungeon.inventory or any(s['operation'] == 'take' and s.get('target_id') == 'longsword' for s in steps)
        if (steps and any(s['operation'] in {'move', 'open', 'wear', 'conceal', 'deceive', 'take'} for s in steps)
                and might_conceal and has_sword and not getattr(self, '_sword_checked', False)):
            ids.add('detect_sword')
        return tuple(r for id in sorted(ids) if (r := self.contextual_check(id)) is not None)

    def _check(self, actor, skill, dc, *, contextual_id=None):
        if contextual_id:
            return self.adjudication.check(contextual_id, actor, skill, dc)
        state, roll, total = ability_check(self.encounter.sheets[actor], self.encounter.states[actor],
                                          skill, dc, self.encounter.roller)
        self.encounter.states[actor] = state
        self._event('check', f'{skill}: {total} contra CD {dc}.', actor_id=actor,
                    perceptible=actor == 'player',
                    skill=skill, dice=list(roll.dice), total=total, dc=dc, passed=total >= dc)
        return total >= dc, total

    def _pay_action(self):
        if self.mode == GameMode.TURN_BASED:
            self.budget = self.budget.spend_action()

    def _pay_interaction(self):
        if self.mode == GameMode.TURN_BASED:
            self.budget = self.budget.spend_interaction()

    def spatial_requirement(self, intent):
        if not isinstance(intent, ScenarioIntent):
            return super().spatial_requirement(intent)
        target, operation = intent.target_id, intent.operation
        if operation == 'investigate':
            area = next((a for a in self.scene.areas if a.id == target), None)
            if area and self.state.position not in area.cells:
                return SpatialRequirement('inside_area', area.id, area.cells)
        elif operation == 'take' and target in self.items and target not in self.dungeon.inventory:
            position = self.remembered_item_position(target)
            if position is not None:
                return self.reach_requirement(target, position, include_target=True)
        elif operation in {'listen', 'unlock'}:
            passage = next((p for p in self.scene.passages if p.id == target), None)
            if passage and (operation != 'unlock' or passage.locked):
                return self.reach_requirement(passage.id, passage.position, include_target=True)
        elif operation == 'wake' and target == 'prisoner' and not self.dungeon.prisoner_awake:
            position = self.prisoner_position if self.dungeon.prisoner_free else self._passage('gate_2').position
            return self.reach_requirement(target, position)
        return None

    def validate_preparation(self, intent):
        super().validate_preparation(intent)
        if not isinstance(intent, ScenarioIntent):
            return
        self.encounter.require_turn(self.encounter.player_id)
        operation, target = intent.operation, intent.target_id
        if operation == 'investigate' and not any(a.id == target for a in self.scene.areas):
            raise ActionError('Cômodo desconhecido.')
        if operation == 'take':
            if target not in self.items or target not in self.known_objects():
                raise ActionError('Encontre o objeto antes de pegá-lo.')
            if target in self.dungeon.inventory:
                raise ActionError('Você já carrega esse objeto.')
            if self.remembered_item_position(target) is None:
                raise ActionError('Você conhece o objeto, mas não uma localização até a qual possa caminhar.')
        if operation in {'listen', 'unlock'}:
            passage = self._passage(target)
            if operation == 'unlock':
                if not passage.locked:
                    return
                if 'cell_key' not in self.dungeon.inventory or target not in {'gate_2', 'gate_3'}:
                    raise ActionError('Você precisa da chave das celas para essa fechadura.')
        if operation == 'wake':
            if target != 'prisoner':
                raise ActionError('Escolha o prisioneiro para acordar.')
            if self.dungeon.prisoner_awake:
                return
        if self.mode == GameMode.TURN_BASED:
            if operation in {'investigate', 'listen', 'wake'} and not self.budget.action_available:
                raise ActionError('A ação deste turno já foi utilizada.')
            if operation in {'take', 'unlock'} and self.budget.free_interaction_used and not self.budget.action_available:
                raise ActionError('A ação deste turno já foi utilizada.')

    def _movement_grid(self):
        # Um guarda incapacitado pode ser atravessado como terreno difícil
        # (PHB 2024, Moving around Other Creatures), mas não é destino livre.
        bodies = frozenset(c.position for c in self.creatures if self.encounter.states[c.id].hp == 0)
        conscious = frozenset(c.position for c in self.creatures if self.encounter.states[c.id].hp > 0)
        grid = replace(self.grid, blocked=self.grid.blocked | conscious | frozenset(o.position for o in self.observers if o.id != 'prisoner'),
                       difficult=self.grid.difficult | bodies)
        if not self.dungeon.prisoner_free:
            grid = replace(grid, blocked=grid.blocked | {self.prisoner_position})
        return grid

    def movement_path(self, intent):
        target = intent.target_id
        position = None
        if target == 'prisoner' and self.prisoner_position in self.visibility.visible:
            if not self.dungeon.prisoner_free:
                goals = self.scene.destination_cells('gate_2')
                return path_to_cells(self._movement_grid(), self.state.position, goals), Decimal('0')
            position = self.prisoner_position
        elif target in self.known_objects():
            position = self.remembered_item_position(target)
            if position is None:
                raise MovementError('Você não conhece uma localização desse objeto.')
        if position is not None:
            goals = frozenset(Position(position.x + dx, position.y + dy)
                              for dx, dy in (*DIRECTIONS.values(), (0, 0))
                              if line_of_sight(Position(position.x + dx, position.y + dy), position,
                                               self.scene.opaque))
            return path_to_cells(self._movement_grid(), self.state.position, goals), Decimal('0')
        return super().movement_path(intent)

    def known_objects(self):
        return {id for id, item in self.items.items()
                if id in self.dungeon.inventory or id in self.dungeon.discovered
                or (id in self.dungeon.exposed_items and self.item_positions[id] in self.visibility.visible)}

    def remembered_item_position(self, id):
        if id in self.dungeon.inventory:
            return self.state.position
        actual = self.item_positions[id]
        if id in self.dungeon.exposed_items and actual in self.visibility.visible:
            return actual
        memories = sorted(self.knowledge.store.select('player', entities=(id,)), key=lambda m: -m.acquired_at)
        for memory in memories:
            if memory.claim.subject_id == id and memory.claim.predicate == 'location':
                if memory.claim.value.startswith('position:'):
                    try:
                        x, y = map(int, memory.claim.value.removeprefix('position:').split(','))
                        remembered = Position(x - 1, y - 1)
                        return remembered if self.grid.contains(remembered) else None
                    except ValueError:
                        return None
                return None
        return None

    def map_view(self):
        visible = self.visibility.visible
        markers = super().map_view()['markers']
        if self.prisoner_position in visible and not self.dungeon.companion_escaped:
            markers.append(dict(kind='ally', label='P', position=coordinate(self.prisoner_position)))
        markers.extend(dict(kind='item', position=coordinate(self.item_positions[id]))
                       for id in self.known_objects() if id not in self.dungeon.inventory
                       and id in self.dungeon.exposed_items and self.item_positions[id] in visible)
        sheet = self.character_context()
        return dict(title=self.title, compact=True, markers=markers,
                    passage_lock_labels=super().map_view()['passage_lock_labels'],
                    equipment=sheet['clothing'] + ' · Itens: ' + (', '.join(sheet['inventory']) or 'nenhum'),
                    legend='P: prisioneiro · dourado: tochas / itens')

    def character_context(self):
        context = super().character_context()
        if hasattr(self, 'dungeon'):
            context['clothing'] = ('Roupa de empregado da limpeza' if self.dungeon.clothing == 'cleaner_uniform'
                                   else 'Trapos de lã')
            context['inventory'] = [self.items[id]['name'] for id in sorted(self.dungeon.inventory)]
            context['sword_concealed'] = self.dungeon.sword_concealed
        return context

